-- Material Shelf-Life & Storage Control System
-- SAME Supabase project as existing Chemical Inventory.
-- Non-destructive: only msl_* objects are created/updated.

create extension if not exists pgcrypto;

create table if not exists public.msl_master_versions (
  id uuid primary key default gen_random_uuid(), version_key text not null unique,
  master_type text not null check (master_type in ('MATERIAL_MAPPING','SHELF_LIFE_STORAGE','WAREHOUSE_RULES')),
  version_label text not null, source_file text not null, source_sha256 text,
  record_count integer not null default 0 check (record_count >= 0),
  status text not null default 'ACTIVE' check (status in ('ACTIVE','SUPERSEDED','REJECTED')),
  imported_at timestamptz not null default now(), note text
);
create table if not exists public.msl_material_groups (
  group_code text primary key, main_category_th text, main_category_en text, main_category_code text,
  sub_category_th text, sub_category_en text, sub_category_code text, material_type_th text, material_type_en text, material_type_code text,
  has_storage_master boolean not null default false, is_active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.msl_material_codes (
  material_code text primary key, group_code text not null references public.msl_material_groups(group_code) on update cascade,
  source_version_id uuid references public.msl_master_versions(id), source_row integer, is_active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.msl_storage_profiles (
  id uuid primary key default gen_random_uuid(), group_code text not null references public.msl_material_groups(group_code) on update cascade,
  profile_no integer not null check (profile_no > 0), source_version_id uuid references public.msl_master_versions(id), source_row integer not null,
  responsible_sqe text, packaging text, shelf_life_text text, shelf_life_months integer check (shelf_life_months is null or shelf_life_months >= 0),
  expiry_calculation_mode text not null default 'UNKNOWN' check (expiry_calculation_mode in ('FIXED_MONTHS','PRODUCT_SPECIFIC','UNKNOWN')),
  storage_temperature text, storage_humidity text, moisture_sensitive boolean, moisture_sensitive_text text, remark text,
  is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(source_version_id, source_row)
);
create index if not exists msl_material_codes_group_idx on public.msl_material_codes(group_code);
create index if not exists msl_storage_profiles_group_idx on public.msl_storage_profiles(group_code);
create table if not exists public.msl_warehouse_rules (
  rule_code text primary key, clause text, title_th text not null, action_text text not null, source_version_id uuid references public.msl_master_versions(id),
  is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.msl_data_issues (
  id uuid primary key default gen_random_uuid(), issue_key text not null unique, issue_type text not null, material_code text, group_code text,
  detail jsonb not null default '{}'::jsonb, status text not null default 'OPEN' check (status in ('OPEN','RESOLVED','ACCEPTED')),
  created_at timestamptz not null default now(), resolved_at timestamptz
);
create table if not exists public.msl_master_import_audit (
  id uuid primary key default gen_random_uuid(), version_id uuid references public.msl_master_versions(id), action text not null,
  inserted_count integer not null default 0, updated_count integer not null default 0, rejected_count integer not null default 0,
  detail jsonb not null default '{}'::jsonb, performed_at timestamptz not null default now()
);

alter table public.msl_master_versions enable row level security;
alter table public.msl_material_groups enable row level security;
alter table public.msl_material_codes enable row level security;
alter table public.msl_storage_profiles enable row level security;
alter table public.msl_warehouse_rules enable row level security;
alter table public.msl_data_issues enable row level security;
alter table public.msl_master_import_audit enable row level security;

do $$ begin
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='msl_master_versions' and policyname='msl_read_master_versions') then create policy msl_read_master_versions on public.msl_master_versions for select to authenticated using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='msl_material_groups' and policyname='msl_read_material_groups') then create policy msl_read_material_groups on public.msl_material_groups for select to authenticated using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='msl_material_codes' and policyname='msl_read_material_codes') then create policy msl_read_material_codes on public.msl_material_codes for select to authenticated using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='msl_storage_profiles' and policyname='msl_read_storage_profiles') then create policy msl_read_storage_profiles on public.msl_storage_profiles for select to authenticated using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='msl_warehouse_rules' and policyname='msl_read_warehouse_rules') then create policy msl_read_warehouse_rules on public.msl_warehouse_rules for select to authenticated using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='msl_data_issues' and policyname='msl_read_data_issues') then create policy msl_read_data_issues on public.msl_data_issues for select to authenticated using(true); end if;
 if not exists(select 1 from pg_policies where schemaname='public' and tablename='msl_master_import_audit' and policyname='msl_read_import_audit') then create policy msl_read_import_audit on public.msl_master_import_audit for select to authenticated using(true); end if;
end $$;

create or replace function public.msl_lookup_material_code(p_material_code text) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_code text:=upper(trim(coalesce(p_material_code,''))); v_group text; v_result jsonb;
begin
 if current_user not in ('postgres','supabase_admin') and coalesce(current_setting('request.jwt.claim.role',true),'')<>'authenticated' then raise exception 'Unauthorized'; end if;
 select group_code into v_group from public.msl_material_codes where material_code=v_code and is_active=true;
 if v_group is null then return jsonb_build_object('found',false,'reason','MATERIAL_CODE_NOT_FOUND','material_code',v_code); end if;
 select jsonb_build_object('found',true,'material_code',v_code,'material_group',g.group_code,
  'requirement_status',case when g.has_storage_master then 'FOUND' else 'NOT_FOUND_IN_MASTER' end,
  'group',jsonb_build_object('main_category_th',g.main_category_th,'main_category_en',g.main_category_en,'sub_category_th',g.sub_category_th,'sub_category_en',g.sub_category_en,'material_type_th',g.material_type_th,'material_type_en',g.material_type_en),
  'storage_profiles',coalesce((select jsonb_agg(jsonb_build_object('profile_no',sp.profile_no,'packaging',sp.packaging,'shelf_life_text',sp.shelf_life_text,'shelf_life_months',sp.shelf_life_months,'expiry_calculation_mode',sp.expiry_calculation_mode,'storage_temperature',sp.storage_temperature,'storage_humidity',sp.storage_humidity,'moisture_sensitive',sp.moisture_sensitive,'remark',sp.remark,'source_row',sp.source_row) order by sp.profile_no) from public.msl_storage_profiles sp where sp.group_code=g.group_code and sp.is_active=true),'[]'::jsonb)) into v_result
 from public.msl_material_groups g where g.group_code=v_group and g.is_active=true; return v_result;
end $$;

create or replace function public.msl_lookup_material_group(p_group_code text) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_group text:=upper(trim(coalesce(p_group_code,''))); v_result jsonb;
begin
 if current_user not in ('postgres','supabase_admin') and coalesce(current_setting('request.jwt.claim.role',true),'')<>'authenticated' then raise exception 'Unauthorized'; end if;
 if not exists(select 1 from public.msl_material_groups where group_code=v_group and is_active=true) then return jsonb_build_object('found',false,'reason','MATERIAL_GROUP_NOT_FOUND','material_group',v_group); end if;
 select jsonb_build_object('found',true,'material_group',g.group_code,'requirement_status',case when g.has_storage_master then 'FOUND' else 'NOT_FOUND_IN_MASTER' end,
  'group',jsonb_build_object('main_category_th',g.main_category_th,'main_category_en',g.main_category_en,'sub_category_th',g.sub_category_th,'sub_category_en',g.sub_category_en,'material_type_th',g.material_type_th,'material_type_en',g.material_type_en),
  'material_codes',coalesce((select jsonb_agg(mc.material_code order by mc.material_code) from public.msl_material_codes mc where mc.group_code=g.group_code and mc.is_active=true),'[]'::jsonb),
  'storage_profiles',coalesce((select jsonb_agg(jsonb_build_object('profile_no',sp.profile_no,'packaging',sp.packaging,'shelf_life_text',sp.shelf_life_text,'shelf_life_months',sp.shelf_life_months,'expiry_calculation_mode',sp.expiry_calculation_mode,'storage_temperature',sp.storage_temperature,'storage_humidity',sp.storage_humidity,'moisture_sensitive',sp.moisture_sensitive,'remark',sp.remark,'source_row',sp.source_row) order by sp.profile_no) from public.msl_storage_profiles sp where sp.group_code=g.group_code and sp.is_active=true),'[]'::jsonb)) into v_result
 from public.msl_material_groups g where g.group_code=v_group and g.is_active=true; return v_result;
end $$;
grant execute on function public.msl_lookup_material_code(text) to authenticated;
grant execute on function public.msl_lookup_material_group(text) to authenticated;

