insert into public.msl_storage_profiles(group_code,profile_no,source_version_id,source_row,responsible_sqe,packaging,shelf_life_text,shelf_life_months,expiry_calculation_mode,storage_temperature,storage_humidity,moisture_sensitive,moisture_sensitive_text,remark,is_active)
select v->>0,(v->>1)::int,ver.id,(v->>2)::int,v->>3,v->>4,v->>5,(v->>6)::int,v->>7,v->>8,v->>9,(v->>10)::boolean,v->>11,v->>12,true from j cross join ver
on conflict(source_version_id,source_row) do update set group_code=excluded.group_code,profile_no=excluded.profile_no,responsible_sqe=excluded.responsible_sqe,packaging=excluded.packaging,shelf_life_text=excluded.shelf_life_text,shelf_life_months=excluded.shelf_life_months,expiry_calculation_mode=excluded.expiry_calculation_mode,storage_temperature=excluded.storage_temperature,storage_humidity=excluded.storage_humidity,moisture_sensitive=excluded.moisture_sensitive,moisture_sensitive_text=excluded.moisture_sensitive_text,remark=excluded.remark,is_active=true,updated_at=now();
with j(v) as (select value from jsonb_array_elements($msl_rules$[["FIFO","5.5.1.6","ควบคุมการจ่ายแบบเข้าก่อนออกก่อน","Follow FIFO unless color difference or matching-set requirement applies; reference tolerance within 2 weeks."],["SEGREGATION","5.5.1.10","แยกจัดเก็บตามประเภทและข้อกำหนดพิเศษ","Store by category; hazardous/special materials require isolation and visible warning/safety identification."],["NO_FLOOR","5.5.1.12","ห้ามวางวัสดุบนพื้นโดยตรง","Use pallet or rack protection."],["STACKING","5.5.1.13","ข้อกำหนดการซ้อน","Small/light on top, large/heavy below; one material per pallet; maximum 160 cm unless a specific requirement applies."],["EXPIRED_HOLD","5.6.1","วัสดุเกินอายุต้องแยกและระบุสถานะ","Warehouse segregates and identifies expired material; disposition requires quality reinspection/review."],["EXPIRED_REINSPECTION","5.1 / 5.6.2","การตรวจซ้ำวัสดุเกินอายุ","Warehouse/material control initiates the expired-material process; IQC performs inspection and records the judgement."]]$msl_rules$::jsonb)), ver as (select id from public.msl_master_versions where version_key='MSL_WH_RULES_HQ_PRD_R_049_2_0')
insert into public.msl_warehouse_rules(rule_code,clause,title_th,action_text,source_version_id,is_active)
select v->>0,v->>1,v->>2,v->>3,ver.id,true from j cross join ver
on conflict(rule_code) do update set clause=excluded.clause,title_th=excluded.title_th,action_text=excluded.action_text,source_version_id=excluded.source_version_id,is_active=true,updated_at=now();
with j(v) as (select value from jsonb_array_elements($msl_issues$[["MISSING_STORAGE_MASTER:B003ZA","MISSING_STORAGE_MASTER","B003ZA",{"material_codes":["B0ZA1179","B0ZA0153"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"],["MISSING_STORAGE_MASTER:F003EC","MISSING_STORAGE_MASTER","F003EC",{"material_codes":["F0EC0030"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"],["MISSING_STORAGE_MASTER:F039L4","MISSING_STORAGE_MASTER","F039L4",{"material_codes":["F0L11078","F0L11077","FL000470","F0L10005","F0L10009"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"],["MISSING_STORAGE_MASTER:M001H0","MISSING_STORAGE_MASTER","M001H0",{"material_codes":["M0H00181","M0H00180"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"],["MISSING_STORAGE_MASTER:Y001C0","MISSING_STORAGE_MASTER","Y001C0",{"material_codes":["YC000131"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"],["MISSING_STORAGE_MASTER:Y001G0","MISSING_STORAGE_MASTER","Y001G0",{"material_codes":["Y0G00049","YD000058"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"],["MISSING_STORAGE_MASTER:Y001K0","MISSING_STORAGE_MASTER","Y001K0",{"material_codes":["YG000062"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"],["MISSING_STORAGE_MASTER:Y00203","MISSING_STORAGE_MASTER","Y00203",{"material_codes":["Y0030060","Y0030147"],"reason":"Exact Material Group code exists in mapping master but no exact group code exists in shelf-life/storage master. Do not guess or auto-alias."},"OPEN"]]$msl_issues$::jsonb))
insert into public.msl_data_issues(issue_key,issue_type,group_code,detail,status)
select v->>0,v->>1,v->>2,v->3,coalesce(v->>4,'OPEN') from j
on conflict(issue_key) do update set detail=excluded.detail,status=case when public.msl_data_issues.status='RESOLVED' then public.msl_data_issues.status else 'OPEN' end;
insert into public.msl_master_import_audit(version_id,action,inserted_count,updated_count,rejected_count,detail)
select id,'INITIAL_SEED',case master_type when 'MATERIAL_MAPPING' then 313 when 'SHELF_LIFE_STORAGE' then 452 else 6 end,0,0,jsonb_build_object('source',source_file)
from public.msl_master_versions v where version_key in ('MSL_MAPPING_2026_08_27','MSL_SHELF_2026_08_27','MSL_WH_RULES_HQ_PRD_R_049_2_0')
and not exists(select 1 from public.msl_master_import_audit a where a.version_id=v.id and a.action='INITIAL_SEED');
commit;

